from dataclasses import dataclass, field, asdict
from typing import Dict, Any, Optional
from datetime import datetime
import json
import uuid


class MatchResultType(str):
    """Typ wyniku meczu"""
    HOME_WIN = "1"      # Wygrana gospodarzy
    DRAW = "X"          # Remis
    AWAY_WIN = "2"      # Wygrana gosci


@dataclass
class MatchResult:
    """
    Model wyniku meczu.
    
    Przechowuje informacje o:
    - Druzynach i wyniku
    - Identyfikatorze meczu
    - Zrodle danych
    - Czasie utworzenia
    
    Powiazany z:
    - PredictionTrace (do weryfikacji predykcji)
    - CouponLaboratory (do ewaluacji kuponow)
    - StrategyMemory (do aktualizacji historii)
    """
    
    # ===== IDENTYFIKACJA =====
    match_id: str = field(default_factory=lambda: f"match_{uuid.uuid4().hex[:12]}")
    
    # ===== DANE MECZU =====
    home_team: str = ""
    away_team: str = ""
    home_goals: int = 0
    away_goals: int = 0
    
    # ===== METADANE =====
    source: str = "wyniki.csv"
    created_at: datetime = field(default_factory=datetime.now)
    metadata: Dict[str, Any] = field(default_factory=dict)
    
    # ===== WLASCIWOSCI =====
    
    @property
    def result(self) -> str:
        """
        Zwraca typ wyniku jako string.
        
        Returns:
            "1" - wygrana gospodarzy
            "X" - remis
            "2" - wygrana gosci
        """
        if self.home_goals > self.away_goals:
            return MatchResultType.HOME_WIN
        elif self.home_goals < self.away_goals:
            return MatchResultType.AWAY_WIN
        else:
            return MatchResultType.DRAW
    
    @property
    def result_tuple(self) -> tuple:
        """Zwraca wynik jako tuple (home_goals, away_goals)"""
        return (self.home_goals, self.away_goals)
    
    @property
    def is_draw(self) -> bool:
        """Czy mecz zakonczyl sie remisem"""
        return self.home_goals == self.away_goals
    
    @property
    def is_home_win(self) -> bool:
        """Czy wygrali gospodarze"""
        return self.home_goals > self.away_goals
    
    @property
    def is_away_win(self) -> bool:
        """Czy wygrali goscie"""
        return self.home_goals < self.away_goals
    
    @property
    def total_goals(self) -> int:
        """Laczna liczba goli w meczu"""
        return self.home_goals + self.away_goals
    
    @property
    def goal_difference(self) -> int:
        """Roznica goli (gospodarze - goscie)"""
        return self.home_goals - self.away_goals
    
    # ===== METODY SERIALIZACJI =====
    
    def to_dict(self) -> Dict[str, Any]:
        """Konwersja do slownika"""
        data = asdict(self)
        # Konwersja datetime do string
        data['created_at'] = self.created_at.isoformat()
        return data
    
    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'MatchResult':
        """Tworzenie z slownika"""
        # Konwersja string do datetime
        if isinstance(data.get('created_at'), str):
            data['created_at'] = datetime.fromisoformat(data['created_at'])
        return cls(**data)
    
    def to_json(self, indent: Optional[int] = None) -> str:
        """Konwersja do JSON"""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)
    
    @classmethod
    def from_json(cls, json_str: str) -> 'MatchResult':
        """Tworzenie z JSON"""
        return cls.from_dict(json.loads(json_str))
    
    # ===== METODY REPREZENTACJI =====
    
    def get_match_key(self) -> str:
        """Zwraca klucz identyfikujacy mecz (dla wyszukiwania)"""
        teams = [self.home_team.strip().lower(), self.away_team.strip().lower()]
        teams.sort()
        return f"{teams[0]}_vs_{teams[1]}"
    
    def get_display_name(self) -> str:
        """Zwraca wy swollenformatowana nazwe meczu"""
        return f"{self.home_team} - {self.away_team}"
    
    def get_score_display(self) -> str:
        """Zwraca wy swollenformatowany wynik"""
        return f"{self.home_goals}:{self.away_goals}"
    
    def __str__(self) -> str:
        return f"{self.get_display_name()} {self.get_score_display()} ({self.result})"
    
    def __repr__(self) -> str:
        return f"MatchResult({self.get_display_name()}, {self.get_score_display()})"
    
    def __eq__(self, other: object) -> bool:
        """Porownanie po kluczowych polach"""
        if not isinstance(other, MatchResult):
            return False
        return (self.home_team == other.home_team and
                self.away_team == other.away_team and
                self.home_goals == other.home_goals and
                self.away_goals == other.away_goals)
    
    def __hash__(self) -> int:
        """Hash po kluczowych polach"""
        return hash((self.home_team, self.away_team, self.home_goals, self.away_goals))


@dataclass
class ImportStatistics:
    """Statystyki importu wynikow"""
    loaded: int = 0
    errors: int = 0
    skipped: int = 0
    duplicates: int = 0
    processing_time: float = 0.0
    
    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)
    
    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'ImportStatistics':
        return cls(**data)
    
    def get_success_rate(self) -> float:
        """Procent udanych importow"""
        total = self.loaded + self.errors + self.skipped
        if total == 0:
            return 0.0
        return (self.loaded / total) * 100
    
    def __str__(self) -> str:
        return (f"Import: {self.loaded} loaded, {self.errors} errors, "
                f"{self.skipped} skipped, {self.duplicates} duplicates")
